let temperature = 28;

if (temperature > 30) {
  console.log("It's hot outside!");
} else if (temperature > 20) {
  console.log("Nice weather!");
} else {
  console.log("It's cold!");
}
// Output: "Nice weather!"

let hasTicket = true;
let age = 15;

if (hasTicket) {
  if (age >= 18) {
    console.log("Welcome to the concert!");
  } else {
    console.log("You need a guardian.");
  }
} else {
  console.log("Please buy a ticket first.");
}
// Output: "You need a guardian."

// Falsy values
if (0)   console.log("0 is truthy");
if ("")  console.log("Empty string is truthy");
if (null) console.log("null is truthy");

// None of these print — they are all falsy

// Truthy values
if ("0")     console.log("\"0\" is truthy");      // prints!
if (-1)      console.log("-1 is truthy");           // prints!
if ([1, 2])  console.log("Non-empty array is truthy"); // prints!

let username = "";
let displayName = username || "Anonymous";
console.log(displayName);  // "Anonymous"

username = "Vishnu";
displayName = username || "Anonymous";
console.log(displayName);  // "Vishnu"

// Using truthiness directly in if
let score = 42;
if (score) {
  console.log("Score exists!");  // prints
}

score = 0;
if (score) {
  console.log("This won't print");  // 0 is falsy!
}

let age = 20;

// With if/else
let status;
if (age >= 18) {
  status = "adult";
} else {
  status = "minor";
}

// With ternary — same result, one line
let status2 = age >= 18 ? "adult" : "minor";

console.log(status);   // "adult"
console.log(status2);  // "adult"

let isLoggedIn = true;
let message = `Welcome, ${isLoggedIn ? "user" : "guest"}`;
console.log(message);  // "Welcome, user"

function calculateDiscount(isMember) {
  return isMember ? 0.2 : 0;
}

console.log(calculateDiscount(true));   // 0.2 (20%)
console.log(calculateDiscount(false));  // 0

let day = "Monday";

switch (day) {
  case "Monday":
    console.log("Start of the work week.");
    break;
  case "Friday":
    console.log("TGIF!");
    break;
  case "Saturday":
  case "Sunday":
    console.log("Weekend!");
    break;
  default:
    console.log("Another day.");
    break;
}
// Output: "Start of the work week."

function handleStatus(code) {
  switch (code) {
    case 200:
      return "Success";
    case 301:
      return "Moved";
    case 404:
      return "Not Found";
    case 500:
      return "Server Error";
    default:
      return "Unknown status: " + code;
  }
}

console.log(handleStatus(200));  // "Success"
console.log(handleStatus(404));  // "Not Found"
console.log(handleStatus(418));  // "Unknown status: 418"

try {
  let data = JSON.parse("{invalid json}");
  console.log(data);
} catch (error) {
  console.log("Something went wrong:", error.message);
}
// Output: "Something went wrong: Unexpected token..."

function divide(a, b) {
  try {
    if (b === 0) throw new Error("Cannot divide by zero");
    return a / b;
  } catch (error) {
    console.log("Error:", error.message);
    return null;
  } finally {
    console.log("Division attempt complete.");
  }
}

console.log(divide(10, 2));   // 5, then "Division attempt complete."
console.log(divide(10, 0));   // "Error: Cannot divide by zero", then null

function calculateArea(width, height) {
  if (typeof width !== "number" || typeof height !== "number") {
    throw new Error("Both width and height must be numbers");
  }
  if (width <= 0 || height <= 0) {
    throw new Error("Dimensions must be positive");
  }
  return width * height;
}

try {
  console.log(calculateArea(5, 10));  // 50
  console.log(calculateArea(-3, 4));  // throws Error!
} catch (e) {
  console.log(e.message);  // "Dimensions must be positive"
}

function parseAge(input) {
  try {
    let age = Number(input);
    if (isNaN(age)) throw new Error("Not a valid number");
    if (age < 0) throw new Error("Age cannot be negative");
    if (age > 150) throw new Error("Age seems unrealistic");
    return age;
  } catch (e) {
    console.log("Validation failed:", e.message);
    throw e;  // rethrow so the caller knows about the error
  }
}

try {
  let age = parseAge("-5");
  console.log("Age:", age);
} catch (e) {
  console.log("Caught in outer scope:", e.message);
}
